import type { Place } from '../game/types'
import { decodePlaces, type PlaceFile } from './placeCodec'

let cache: Promise<Place[]> | undefined

/**
 * The curated place dataset (generated by `npm run build:places`). Loaded on demand as its
 * own chunk, so it doesn't weigh down the initial bundle.
 */
export function loadPlaces(): Promise<Place[]> {
  cache ??= import('./places.json').then((m) => decodePlaces(m.default as PlaceFile))
  return cache
}
